import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { add_product_admins } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    addDialog: Boolean
    // userArray: Array,
  },
  mixins: [get_all_org_users],
  data() {
    return {
      selectTeam: "",
      loading: false,
      searchF: null,
      userArray: []
    };
  },
  watch: {
    addDialog: {
      async handler() {
        this.$store.commit("Setnamesearch", this.searchF);
        await this.get_all_org_users();
        await this.fetch_details();
      },
      immediate: true
    },
    async searchF() {
      if (this.searchF != null) {
        if (this.searchF.length >= 3) {
          this.$store.commit("Setnamesearch", this.searchF);
          await this.get_all_org_users();
          await this.fetch_details();
        }
      }
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.selectTeam = "";
      this.searchF = null;
      this.$refs.form.resetValidation();
    },
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userArray.push({
            label: element.full_user_name,
            value: element.user_email_id
          });
        }
      });
      this.userArray.sort((a, b) => a.label.localeCompare(b.label));
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      // console.log(valid);
      if (valid) {
        this.grant_admin_access();
      }
    },
    async grant_admin_access() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(add_product_admins, {
          input: {
            user_email_id: this.selectTeam,
            product_id: this.$store.getters.Getproductitems.product_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.add_product_admins);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$emit("adminRefresh", "refresh");
          this.selectTeam = "";
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
